from flask import Flask
app = Flask(__name__)
HTML = """<html><head><meta name='viewport' content='width=device-width,initial-scale=1'><style>body{font-family:Arial;background:#020617;color:#fff;padding:10px} .card{background:#0f172a;padding:18px;border-radius:20px;max-width:460px;margin:auto;border:1px solid #1e293b} .tab{padding:8px 12px;border-radius:20px;background:#1e293b;color:#94a3b8;border:1px solid #334155;cursor:pointer;font-size:12px} .tab.active{background:#3b82f6;color:#fff} .big{font-size:44px;font-weight:bold;text-align:center;margin:12px 0} .sig{font-size:22px;font-weight:bold;text-align:center;padding:12px;border-radius:12px}</style></head><body><div class=card><h2>Alufx ULTIMATE</h2><p style=color:#22c55e>LIVE REAL Deriv</p><p id=status style=color:#fbbf24;font-size:11px>Connecting...</p><div><button class=tab id=t0 onclick=setPair('R_20')>Vol 20</button> <button class=tab id=t1 onclick=setPair('R_100')>GainX400</button> <button class=tab id=t2 onclick=setPair('stpRNG500')>Step 500</button> <button class=tab id=t3 onclick=setPair('stpRNG400')>Step 400</button></div><div id=title style=text-align:center;color:#f59e0b;margin-top:10px>Volatility 20</div><div class=big id=bigPrice>--</div><div class=sig id=bigSig style=background:#1e293b>Waiting...</div><p id=log style=font-size:10px;color:#334155></p><p style=font-size:10px;color:#475569>Links: ?pair=R_20 ?pair=R_100 ?pair=stpRNG500 ?pair=stpRNG400</p></div><script>
let cur=new URLSearchParams(location.search).get('pair')||'R_20'; const names={"R_20":"Volatility 20","R_100":"GainX400","stpRNG500":"Step 500","stpRNG400":"Step 400"};
function setPair(p){cur=p; document.querySelectorAll('.tab').forEach(t=>t.classList.remove('active')); const m={"R_20":0,"R_100":1,"stpRNG500":2,"stpRNG400":3}; document.getElementById('t'+m[p]).classList.add('active'); document.getElementById('title').innerText=names[p]+' ('+p+')'; history.replaceState(null,'','?pair='+p); document.getElementById('bigPrice').innerText='--';}
setPair(cur);
function conn(){const ws=new WebSocket('wss://ws.derivws.com/websockets/v3?app_id=1089'); ws.onopen=()=>{document.getElementById('status').innerText='Connected'; ["R_20","R_100","stpRNG500","stpRNG400"].forEach(s=>ws.send(JSON.stringify({ticks:s,subscribe:1})))}; ws.onmessage=(e)=>{const d=JSON.parse(e.data); if(d.tick){const s=d.tick.symbol; const pr=parseFloat(d.tick.quote).toFixed(2); if(s===cur){let dir='BUY'; let col='#22c55e'; let bg='#052e16'; const prev=window['_'+s]||pr; if(pr<prev){dir='SELL'; col='#ef4444'; bg='#450a0a';} window['_'+s]=pr; document.getElementById('bigPrice').innerText=pr; document.getElementById('bigPrice').style.color=col; document.getElementById('bigSig').innerText=dir+' '+names[s]; document.getElementById('bigSig').style.background=bg; document.getElementById('bigSig').style.color=col; document.getElementById('bigSig').style.border='1px solid '+col; document.getElementById('log').innerText='REAL: '+s+' '+pr+' @ '+new Date().toLocaleTimeString();}}}; ws.onclose=()=>setTimeout(conn,1500); ws.onerror=()=>setTimeout(conn,1500);}conn();
</script></body></html>"""

@app.route('/')
def home():
    return HTML

@app.route('/health')
def health():
    return "OK"
